output += '\n';
output += 'Entries by Level:\n';

const sortedLevels = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
    output += `  ${level}: ${count}\n`;
}

output += '\n';

let maxErrorComponent = '';
let maxErrorCount = 0;
for (const [comp, count] of errorComponentCounts) {
    if (count > maxErrorCount || (count === maxErrorCount && comp < maxErrorComponent)) {
        maxErrorCount = count;
        maxErrorComponent = comp;
    }
}
output += `Component with Most Errors: ${maxErrorComponent} (${maxErrorCount} errors)\n`;
output += '\n';

output += 'Unique Error Messages:\n';
const sortedMessages = [...errorMessages].sort();
for (const msg of sortedMessages) {
    output += `  - ${msg}\n`;
}

output += '\n';

