declare const require: (id: string) => any;

const fs = require("fs");

type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

function isObject(val: unknown): val is { [key: string]: JsonValue } {
  return val !== null && typeof val === "object" && !Array.isArray(val);
}

function isArray(val: unknown): val is JsonValue[] {
  return Array.isArray(val);
}

function deepMerge(a: JsonValue, b: JsonValue): JsonValue {
  if (isObject(a) && isObject(b)) {
    const result: { [key: string]: JsonValue } = {};
    const allKeys = new Set<string>([...Object.keys(a), ...Object.keys(b)]);
    for (const key of allKeys) {
      if (key in a && key in b) {
        result[key] = deepMerge(a[key], b[key]);
      } else if (key in a) {
        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }
    return result;
  }
  if (isArray(a) && isArray(b)) {
    const result: JsonValue[] = [...a];
    for (const item of b) {
      const itemStr = JSON.stringify(item);
      if (!result.some((existing) => JSON.stringify(existing) === itemStr)) {
        result.push(item);
      }
    }
    return result;
  }
  return b;
}

function sortKeys(val: JsonValue): JsonValue {
  if (isObject(val)) {
    const sorted: { [key: string]: JsonValue } = {};
    const keys = Object.keys(val).sort();
    for (const key of keys) {
      sorted[key] = sortKeys(val[key]);
    }
    return sorted;
  }
  if (isArray(val)) {
    return val.map((item) => sortKeys(item));
  }
  return val;
}

