        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }
    return result;
  }
  if (isArray(a) && isArray(b)) {
    const result: JsonValue[] = [...a];
    for (const item of b) {
      const itemStr = JSON.stringify(item);
      if (!result.some((existing) => JSON.stringify(existing) === itemStr)) {
        result.push(item);
      }
    }
    return result;
  }
  return b;
}

function sortKeys(val: JsonValue): JsonValue {
  if (isObject(val)) {
    const sorted: { [key: string]: JsonValue } = {};
    const keys = Object.keys(val).sort();
    for (const key of keys) {
      sorted[key] = sortKeys(val[key]);
    }
    return sorted;
  }
  if (isArray(val)) {
    return val.map((item) => sortKeys(item));
  }
  return val;
}

