    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_avg(avg: f64) -> String {
    let integer_part = avg as u64;
    let decimal_part = ((avg - integer_part as f64) * 100.0).round() as u64;
    let int_str = format_number_with_commas(integer_part);
    format!("{}.{}", int_str, format!("{:02}", decimal_part))
