import * as fs from 'fs';

const filePath = '<tmp>';
const content = fs.readFileSync(filePath, 'utf-8');
const lines = content.replace(/^\uFEFF/, '').trim().split('\n');

interface Employee {
  employee_id: string;
  name: string;
  department: string;
  salary: number;
  start_date: string;
  rating: string;
}

const employees: Employee[] = [];

for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  const parts = line.split(',');
  if (parts.length < 6) continue;
  employees.push({
    employee_id: parts[0].trim(),
    name: parts[1].trim(),
    department: parts[2].trim(),
    salary: parseFloat(parts[3].trim()),
    start_date: parts[4].trim(),
    rating: parts[5].trim()
  });
}

function formatWithCommas(n: number, decimals: number): string {
  const fixed = n.toFixed(decimals);
  const parts = fixed.split('.');
  let intPart = parts[0];
  const decimalPart = parts[1] || '';

  let negative = false;
  if (intPart.startsWith('-')) {
    negative = true;
    intPart = intPart.slice(1);
  }

  let formatted = '';
  for (let i = intPart.length - 1, count = 0; i >= 0; i--, count++) {
    if (count > 0 && count % 3 === 0) formatted = ',' + formatted;
    formatted = intPart[i] + formatted;
  }

  if (negative) formatted = '-' + formatted;
  if (decimals > 0 && decimalPart) formatted += '.' + decimalPart;
  return formatted;
}

// Average salary by department
const deptData: Map<string, { total: number; count: number }> = new Map();
for (const emp of employees) {
  const existing = deptData.get(emp.department) || { total: 0, count: 0 };
  existing.total += emp.salary;
  existing.count += 1;
  deptData.set(emp.department, existing);
}

const sortedDepts = Array.from(deptData.keys()).sort();

// Highest paid
let highestPaid = employees[0];
for (const emp of employees) {
  if (emp.salary > highestPaid.salary) {
    highestPaid = emp;
  }
}

// Departments with >2 employees
const deptCounts: Map<string, number> = new Map();
for (const emp of employees) {
  deptCounts.set(emp.department, (deptCounts.get(emp.department) || 0) + 1);
}
const deptsOver2: Array<[string, number]> = Array.from(deptCounts.entries())
  .filter(([, count]) => count > 2)
  .sort((a, b) => a[0].localeCompare(b[0]));

// Total budget
const totalBudget = employees.reduce((sum, emp) => sum + emp.salary, 0);

// Build output
const out: string[] = [];
out.push('=== Salary Report ===');
out.push('');
out.push('Average Salary by Department:');
for (const dept of sortedDepts) {
  const { total, count } = deptData.get(dept)!;
  const avg = total / count;
  out.push(`  ${dept}: $${formatWithCommas(avg, 2)}`);
}
out.push('');
out.push(`Highest Paid: ${highestPaid.name} ($${formatWithCommas(Math.round(highestPaid.salary), 0)})`);
out.push('');
out.push('Departments with >2 employees:');
for (const [dept, count] of deptsOver2) {
  out.push(`  ${dept} (${count} employees)`);
}
out.push('');
out.push(`Total Budget: $${formatWithCommas(Math.round(totalBudget), 0)}`);

process.stdout.write(out.join('\n') + '\n');

