        for key in dictA.keys {
            result[key] = dictA[key]
        }
        for key in dictB.keys {
            let bVal = dictB[key]!
            if let aVal = dictA[key] {
                result[key] = merge(a: aVal, b: bVal)
            } else {
                result[key] = bVal
            }
        }
        return result
    }
    if let arrA = a as? [Any], let arrB = b as? [Any] {
        var result: [Any] = []
        var seen: Set<String> = []
        for item in arrA {
            let key = jsonToComparable(item)
            if !seen.contains(key) {
                seen.insert(key)
                result.append(item)
            }
        }
        for item in arrB {
            let key = jsonToComparable(item)
            if !seen.contains(key) {
                seen.insert(key)
                result.append(item)
            }
        }
        return result
    }
    return b
}

