import * as http from 'http';

interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  stock: number;
}

const options: http.RequestOptions = {
  hostname: '127.0.0.1',
  port: 18923,
  path: '/api/products',
  method: 'GET',
};

const req = http.request(options, (res: http.IncomingMessage) => {
  let data = '';
  res.on('data', (chunk: string) => {
    data += chunk;
  });
  res.on('end', () => {
    const products: Product[] = JSON.parse(data);
    const filtered = products.filter((p) => p.price > 50.00);
    filtered.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));

    const out: string[] = [];
    out.push('=== Filtered Products (price > $50.00) ===');
    out.push('');
    for (const p of filtered) {
      out.push(`${p.name}: $${p.price.toFixed(2)}`);
    }
    out.push('');
    out.push(`Count: ${filtered.length}`);
    const total = filtered.reduce((sum, p) => sum + p.price, 0);
    out.push(`Total: $${total.toFixed(2)}`);

    process.stdout.write(out.join('\n') + '\n');
  });
});

req.on('error', (err: Error) => {
  process.stderr.write(err.message + '\n');
  process.exit(1);
});

req.end();

