use std::collections::BTreeMap;
use std::collections::BTreeSet;
use std::fs;

fn main() {
    let content = fs::read_to_string("<tmp>")
        .expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let close_bracket = line.find(']').unwrap();
        let timestamp_part = &line[1..close_bracket];

        let hour: u32 = timestamp_part[11..13].parse().unwrap();
        *hour_counts.entry(hour).or_insert(0) += 1;

        let after_bracket = line[close_bracket + 1..].trim_start();
        let space_idx = after_bracket.find(' ').unwrap();
        let level = &after_bracket[..space_idx];
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        let rest = &after_bracket[space_idx..];
        let open_paren = rest.find('(').unwrap();
        let close_paren = rest.find(')').unwrap();
        let component = &rest[open_paren + 1..close_paren];

        let after_paren = &rest[close_paren + 1..];
        let message = after_paren.trim_start_matches(" - ").to_string();

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message);
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();
    let (top_component, top_count) = error_component_counts.iter()
        .max_by_key(|(_, c)| c)
        .expect("No errors found");
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();
    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();
    let (busiest_hour, busiest_count) = hour_counts.iter()
        .max_by_key(|(_, c)| c)
        .expect("No entries found");
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

