interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface Graph {
  nodes: string[];
  edges: Edge[];
}

function main(): void {
  const filePath = '<tmp>';
  const raw: string = fs.readFileSync(filePath, 'utf-8');
  const data: Graph = JSON.parse(raw);

  const nodes: string[] = data.nodes;
  const edges: Edge[] = data.edges;

  // Build adjacency list (undirected)
  const adj: Map<string, { to: string; weight: number }[]> = new Map();
  for (const node of nodes) {
    adj.set(node, []);
  }
  for (const edge of edges) {
    adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
    adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
  }

  // Dijkstra's algorithm from node "A"
  const dist: Map<string, number> = new Map();
  for (const node of nodes) {
    dist.set(node, Infinity);
  }
  dist.set('A', 0);

  const visited: Set<string> = new Set();

  for (let i = 0; i < nodes.length; i++) {
    // Find unvisited node with minimum distance
    let u: string | null = null;
    let minDist: number = Infinity;
    for (const node of nodes) {
      if (!visited.has(node)) {
        const d = dist.get(node)!;
        if (d < minDist) {
          minDist = d;
          u = node;
        }
      }
    }

    if (u === null) break;
    visited.add(u);

    // Relax all edges from u
    const neighbors = adj.get(u)!;
    for (const { to, weight } of neighbors) {
      if (!visited.has(to)) {
        const newDist = dist.get(u)! + weight;
        if (newDist < dist.get(to)!) {
          dist.set(to, newDist);
        }
      }
    }
  }

  // Output results sorted alphabetically
  const sorted: string[] = [...nodes].sort();
  const lines: string[] = [];
  lines.push('=== Shortest Paths from A ===');
  lines.push('');
  for (const node of sorted) {
    lines.push(`A -> ${node}: ${dist.get(node)}`);
  }
  process.stdout.write(lines.join('\n') + '\n');
}

main();

