import java.io.*;
import java.util.*;
import java.nio.file.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";
        String json = new String(Files.readAllBytes(Paths.get(filePath)));

        List<String> nodes = new ArrayList<>();
        List<String[]> edgeList = new ArrayList<>();
        List<Integer> weightList = new ArrayList<>();

        // Parse nodes
        int nodesStart = json.indexOf("\"nodes\"");
        nodesStart = json.indexOf('[', nodesStart);
        int nodesEnd = json.indexOf(']', nodesStart);
        String nodesStr = json.substring(nodesStart + 1, nodesEnd).trim();
        if (!nodesStr.isEmpty()) {
            String[] parts = nodesStr.split(",");
            for (String p : parts) {
                nodes.add(p.trim().replace("\"", ""));
            }
        }

        // Parse edges
        int edgesStart = json.indexOf("\"edges\"");
        edgesStart = json.indexOf('[', edgesStart);
        int depth = 0;
        int edgesEnd = -1;
        for (int i = edgesStart; i < json.length(); i++) {
            if (json.charAt(i) == '[') depth++;
            else if (json.charAt(i) == ']') {
                depth--;
                if (depth == 0) {
                    edgesEnd = i;
                    break;
                }
            }
        }
        String edgesStr = json.substring(edgesStart + 1, edgesEnd).trim();

        int pos = 0;
        while (pos < edgesStr.length()) {
            int objStart = edgesStr.indexOf('{', pos);
            if (objStart == -1) break;
            int objEnd = edgesStr.indexOf('}', objStart);
            String obj = edgesStr.substring(objStart, objEnd + 1);

            String from = extractString(obj, "from");
            String to = extractString(obj, "to");
            int weight = extractInt(obj, "weight");

            edgeList.add(new String[]{from, to});
            weightList.add(weight);

            pos = objEnd + 1;
        }

        // Build adjacency list (undirected)
        Map<String, List<String>> adj = new HashMap<>();
        Map<String, List<Integer>> adjW = new HashMap<>();
        for (String node : nodes) {
            adj.put(node, new ArrayList<>());
            adjW.put(node, new ArrayList<>());
        }
        for (int j = 0; j < edgeList.size(); j++) {
            String from = edgeList.get(j)[0];
            String to = edgeList.get(j)[1];
            int w = weightList.get(j);
            adj.get(from).add(to);
            adjW.get(from).add(w);
            adj.get(to).add(from);
            adjW.get(to).add(w);
        }

        // Dijkstra's algorithm
        Map<String, Integer> dist = new HashMap<>();
        for (String node : nodes) {
            dist.put(node, Integer.MAX_VALUE);
        }
        dist.put("A", 0);

        Map<String, Integer> nodeIdx = new HashMap<>();
        for (int idx = 0; idx < nodes.size(); idx++) {
            nodeIdx.put(nodes.get(idx), idx);
        }

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        pq.offer(new int[]{nodeIdx.get("A"), 0});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int uIdx = curr[0];
            int d = curr[1];
            String u = nodes.get(uIdx);

            if (d > dist.get(u)) continue;

            List<String> neighbors = adj.get(u);
            List<Integer> weights = adjW.get(u);
            for (int k = 0; k < neighbors.size(); k++) {
                String v = neighbors.get(k);
                int w = weights.get(k);
                int nd = d + w;
                if (nd < dist.get(v)) {
                    dist.put(v, nd);
                    pq.offer(new int[]{nodeIdx.get(v), nd});
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        Collections.sort(nodes);
        for (String node : nodes) {
            System.out.println("A -> " + node + ": " + dist.get(node));
        }
    }

    static String extractString(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        idx = obj.indexOf(':', idx);
        idx = obj.indexOf('"', idx + 1);
        int end = obj.indexOf('"', idx + 1);
        return obj.substring(idx + 1, end);
    }

    static int extractInt(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        idx = obj.indexOf(':', idx);
        idx++;
        while (idx < obj.length() && (obj.charAt(idx) == ' ' || obj.charAt(idx) == '\t')) idx++;
        int end = idx;
        while (end < obj.length() && (Character.isDigit(obj.charAt(end)) || obj.charAt(end) == '-')) end++;
        return Integer.parseInt(obj.substring(idx, end));
    }
}

