            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.s.get(self.pos).copied()
    }

    fn expect(&mut self, c: char) {
        self.skip_ws();
        assert_eq!(self.peek(), Some(c), "expected '{}' at pos {}", c, self.pos);
        self.pos += 1;
    }

    fn parse_value(&mut self) -> Val {
        self.skip_ws();
        match self.peek() {
            Some('"') => Val::Str(self.parse_string()),
            Some('[') => Val::Arr(self.parse_array()),
            Some('{') => Val::Obj(self.parse_object()),
            Some(_) => Val::Num(self.parse_number()),
            None => panic!("unexpected end of input"),
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut result = String::new();
        while self.pos < self.s.len() {
            let c = self.s[self.pos];
            if c == '\\' {
                self.pos += 1;
                let esc = self.s[self.pos];
                match esc {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'n' => result.push('\n'),
                    't' => result.push('\t'),
                    'r' => result.push('\r'),
                    'b' => result.push('\u{0008}'),
                    'f' => result.push('\u{000C}'),
                    'u' => {
                        let hex: String = self.s[self.pos + 1..self.pos + 5].iter().collect();
                        let code = u32::from_str_radix(&hex, 16).unwrap();
                        result.push(char::from_u32(code).unwrap());
                        self.pos += 4;
                    }
                    _ => result.push(esc),
                }
                self.pos += 1;
            } else if c == '"' {
                self.pos += 1;
                break;
            } else {
                result.push(c);
                self.pos += 1;
            }
        }
        result
    }

    fn parse_number(&mut self) -> f64 {
