        self.expect('[');
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') {
            self.pos += 1;
            return arr;
        }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.pos += 1; }
                Some(']') => { self.pos += 1; break; }
                _ => panic!("expected ',' or ']' in array"),
            }
        }
        arr
    }

    fn parse_object(&mut self) -> Vec<(String, Val)> {
        self.expect('{');
        let mut obj = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') {
            self.pos += 1;
