import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class FileEntry {
        String relPath;
        long lines;
        long chars;
        FileEntry(String relPath, long lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<FileEntry>> groups = new TreeMap<>();
        List<Path> files = new ArrayList<>();
        walkDir(root, files);

        for (Path file : files) {
            String relPath = root.relativize(file).toString().replace('\\', '/');
            long lines = countLines(file);
            long chars = Files.size(file);
            String ext = getExtension(file.getFileName().toString());
            groups.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileEntry(relPath, lines, chars));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileEntry>> entry : groups.entrySet()) {
            String ext = entry.getKey();
            List<FileEntry> list = entry.getValue();
            list.sort(Comparator.comparing(e -> e.relPath));

            long gLines = 0;
            long gChars = 0;
            for (FileEntry fe : list) {
                gLines += fe.lines;
                gChars += fe.chars;
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(list.size()).append("\n");
            sb.append("  Total Lines: ").append(gLines).append("\n");
            sb.append("  Total Characters: ").append(gChars).append("\n");
            for (FileEntry fe : list) {
                sb.append("    ").append(fe.relPath).append(": ").append(fe.lines).append(" lines, ").append(fe.chars).append(" chars\n");
            }

            totalFiles += list.size();
            totalLines += gLines;
            totalChars += gChars;
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    static void walkDir(Path root, List<Path> files) throws IOException {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(root)) {
            for (Path path : stream) {
                if (Files.isSymbolicLink(path)) continue;
                if (Files.isDirectory(path)) {
                    walkDir(path, files);
                } else if (Files.isRegularFile(path)) {
                    files.add(path);
                }
            }
        }
    }

    static long countLines(Path file) throws IOException {
        long count = 0;
        try (BufferedReader reader = Files.newBufferedReader(file)) {
            while (reader.readLine() != null) {
                count++;
            }
        }
        return count;
    }

    static String getExtension(String filename) {
        int lastDot = filename.lastIndexOf('.');
        if (lastDot > 0) {
            return filename.substring(lastDot);
        }
        return "(none)";
    }
}

