#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *run_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;

    size_t cap = 4096;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) { pclose(fp); return NULL; }

    size_t n;
    while ((n = fread(buf + len, 1, cap - len - 1, fp)) > 0) {
        len += n;
        if (cap - len - 1 == 0) {
            cap *= 2;
            char *tmp = (char *)realloc(buf, cap);
            if (!tmp) { pclose(fp); free(buf); return NULL; }
            buf = tmp;
        }
    }
    buf[len] = '\0';
    pclose(fp);

    while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r' ||
                       buf[len - 1] == ' '  || buf[len - 1] == '\t')) {
        buf[--len] = '\0';
    }

    return buf;
}

int main(void) {
    char *os   = run_command("uname -s");
    char *arch = run_command("uname -m");
    char *user = run_command("whoami");
    char *host = run_command("hostname");

    if (!os || !arch || !user || !host) {
        fprintf(stderr, "Error: failed to run a command\n");
        free(os); free(arch); free(user); free(host);
        return 1;
    }

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", host);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", arch);
    printf("  \"username\": \"%s\"\n", user);
    printf("}\n");

    free(os);
    free(arch);
    free(user);
    free(host);

    return 0;
}

