    return strcmp(((NameCount *)a)->name, ((NameCount *)b)->name);
}

int main(void) {
    const char *filepath =
        "<tmp>";

    FILE *f = fopen(filepath, "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    NameCount *levels = NULL;
    int nlevels = 0, caplevels = 0;

    NameCount *errComps = NULL;
    int nerrComps = 0, caperrComps = 0;

