        char *close_bracket = strchr(line, ']');
        if (!close_bracket) continue;

        if (len > 13) {
            int hour = (line[11] - '0') * 10 + (line[12] - '0');
            if (hour >= 0 && hour < 24) hours[hour]++;
        }

        char *rest = close_bracket + 1;
        if (*rest == ' ') rest++;

        char *level_end = strchr(rest, ' ');
        if (!level_end) continue;
        *level_end = '\0';
        char *level = rest;

        rest = level_end + 1;
        if (*rest != '(') continue;
        rest++;
        char *close_paren = strchr(rest, ')');
        if (!close_paren) continue;
        *close_paren = '\0';
        char *component = rest;

