            rest += 3;
        } else {
            continue;
        }
        char *message = rest;

        size_t msglen = strlen(message);
        if (msglen > 0 && message[msglen - 1] == '\n') message[msglen - 1] = '\0';
        if (msglen > 1 && message[msglen - 1] == '\r') message[msglen - 2] = '\0';

        int found = 0;
        for (int i = 0; i < nlevels; i++) {
            if (strcmp(levels[i].name, level) == 0) {
