            if (nlevels == caplevels) {
                caplevels = caplevels ? caplevels * 2 : 16;
                levels = realloc(levels, caplevels * sizeof(NameCount));
                if (!levels) return 1;
            }
            levels[nlevels].name = strdup(level);
            levels[nlevels].count = 1;
            nlevels++;
        }

        if (strcmp(level, "ERROR") == 0) {
            found = 0;
            for (int i = 0; i < nerrComps; i++) {
                if (strcmp(errComps[i].name, component) == 0) {
                    errComps[i].count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (nerrComps == caperrComps) {
                    caperrComps = caperrComps ? caperrComps * 2 : 16;
                    errComps = realloc(errComps, caperrComps * sizeof(NameCount));
                    if (!errComps) return 1;
                }
                errComps[nerrComps].name = strdup(component);
                errComps[nerrComps].count = 1;
                nerrComps++;
            }

            found = 0;
            for (int i = 0; i < nerrMsgs; i++) {
                if (strcmp(errMsgs[i], message) == 0) {
                    found = 1;
                    break;
                }
