                    errMsgs = realloc(errMsgs, caperrMsgs * sizeof(char *));
                    if (!errMsgs) return 1;
                }
                errMsgs[nerrMsgs] = strdup(message);
                nerrMsgs++;
            }
        }
    }

    free(line);
    fclose(f);

    qsort(levels, nlevels, sizeof(NameCount), cmp_namecount);
    qsort(errMsgs, nerrMsgs, sizeof(char *), cmp_str);

    int maxIdx = -1;
    int maxCount = 0;
    for (int i = 0; i < nerrComps; i++) {
        if (errComps[i].count > maxCount) {
            maxCount = errComps[i].count;
            maxIdx = i;
        }
    }

    int busiestHour = 0;
    int busiestCount = 0;
    for (int i = 0; i < 24; i++) {
        if (hours[i] > busiestCount) {
            busiestCount = hours[i];
            busiestHour = i;
        }
    }

    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < nlevels; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
