import * as fs from 'fs';
import * as path from 'path';

const ROOT = '<tmp>';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(buf: Buffer): number {
  if (buf.length === 0) return 0;
  let lines = 0;
  for (let i = 0; i < buf.length; i++) {
    if (buf[i] === 0x0a) lines++;
  }
  if (buf[buf.length - 1] !== 0x0a) lines++;
  return lines;
}

function walk(dir: string, root: string, visited: Set<string>, result: Map<string, FileInfo[]>): void {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      const realPath = fs.realpathSync(fullPath);
      if (visited.has(realPath)) continue;
      visited.add(realPath);
      walk(fullPath, root, visited, result);
    } else if (entry.isFile()) {
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      const buf = fs.readFileSync(fullPath);
      const chars = buf.length;
      const lines = countLines(buf);

      const ext = path.extname(entry.name);
      const extKey = ext || '(no extension)';

      if (!result.has(extKey)) result.set(extKey, []);
      result.get(extKey)!.push({ relativePath, lines, chars });
    }
  }
}

function main(): void {
  const visited = new Set<string>();
  visited.add(fs.realpathSync(ROOT));

  const result = new Map<string, FileInfo[]>();
  walk(ROOT, ROOT, visited, result);

  const exts = Array.from(result.keys()).sort();

  let totalFiles = 0;
  let totalLines = 0;
  let totalChars = 0;

  const output: string[] = [];
  output.push('=== File Tree Analysis ===');
  output.push('');

  for (const ext of exts) {
    const files = result.get(ext)!;
    files.sort((a, b) => (a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0));

    let extLines = 0;
    let extChars = 0;
    for (const f of files) {
      extLines += f.lines;
      extChars += f.chars;
    }

    totalFiles += files.length;
    totalLines += extLines;
    totalChars += extChars;

    output.push(`Extension: ${ext}`);
    output.push(`  Files: ${files.length}`);
    output.push(`  Total Lines: ${extLines}`);
    output.push(`  Total Characters: ${extChars}`);
    for (const f of files) {
      output.push(`    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars`);
    }
  }

  output.push('');
  output.push(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);

  process.stdout.write(output.join('\n') + '\n');
}

main();

