        Ok(f) => f,
        Err(_) => return (0, 0),
    };
    if file.read_to_end(&mut contents).is_err() {
        return (0, 0);
    }

    let chars = contents.len();

    let lines = if contents.is_empty() {
        0
    } else {
        let newline_count = contents.iter().filter(|&&b| b == b'\n').count();
        if contents[contents.len() - 1] == b'\n' {
            newline_count
        } else {
            newline_count + 1
        }
    };

    (lines, chars)
