        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int sum = 0;
                for (int k = 0; k < n; k++) {
                    sum += A[i][k] * B[k][j];
                }
                C[i][j] = sum;
            }
        }

        int det = C[0][0] * (C[1][1] * C[2][2] - C[1][2] * C[2][1])
                 - C[0][1] * (C[1][0] * C[2][2] - C[1][2] * C[2][0])
