use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

fn skip_ws(s: &str, i: &mut usize) {
    while *i < s.len() && s.as_bytes()[*i].is_ascii_whitespace() {
        *i += 1;
    }
}

fn unescape_json_string(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('"') => result.push('"'),
                Some('\\') => result.push('\\'),
                Some('/') => result.push('/'),
                Some('n') => result.push('\n'),
                Some('t') => result.push('\t'),
                Some('r') => result.push('\r'),
                Some('b') => result.push('\u{0008}'),
                Some('f') => result.push('\u{000C}'),
                Some('u') => {
                    let mut hex = String::new();
                    for _ in 0..4 {
                        hex.push(chars.next().unwrap());
                    }
                    let code = u32::from_str_radix(&hex, 16).unwrap();
                    result.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                }
                Some(other) => result.push(other),
                None => {}
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn parse_string(s: &str, i: &mut usize) -> String {
    *i += 1;
    let start = *i;
    while *i < s.len() {
        if s.as_bytes()[*i] == b'\\' {
            *i += 2;
        } else if s.as_bytes()[*i] == b'"' {
            break;
        } else {
            *i += 1;
        }
    }
    let raw = &s[start..*i];
    *i += 1;
    unescape_json_string(raw)
}

fn parse_number(s: &str, i: &mut usize) -> f64 {
    let start = *i;
    while *i < s.len() {
        let c = s.as_bytes()[*i];
        if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
            *i += 1;
        } else {
            break;
        }
    }
    s[start..*i].parse::<f64>().unwrap()
}

fn parse_value(s: &str, i: &mut usize) -> Json {
    skip_ws(s, i);
    if *i >= s.len() {
        return Json::Null;
    }
    let c = s.as_bytes()[*i];
    match c {
