#define BASE "<tmp>"

struct FileInfo {
    char *relpath;
    char *ext;
    long lines;
    long chars;
};

struct FileList {
    struct FileInfo *items;
    int count;
    int capacity;
};

static void file_list_init(struct FileList *fl) {
    fl->items = NULL;
    fl->count = 0;
    fl->capacity = 0;
}

static void file_list_add(struct FileList *fl, const char *relpath, const char *ext, long lines, long chars) {
    if (fl->count == fl->capacity) {
        fl->capacity = fl->capacity ? fl->capacity * 2 : 64;
        fl->items = (struct FileInfo *)realloc(fl->items, (size_t)fl->capacity * sizeof(struct FileInfo));
        if (!fl->items) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    fl->items[fl->count].relpath = strdup(relpath);
    fl->items[fl->count].ext = strdup(ext);
    fl->items[fl->count].lines = lines;
    fl->items[fl->count].chars = chars;
    if (!fl->items[fl->count].relpath || !fl->items[fl->count].ext) { fprintf(stderr, "OOM\n"); exit(1); }
    fl->count++;
}

static void count_file(const char *path, long *lines, long *chars) {
    FILE *f = fopen(path, "rb");
    if (!f) { *lines = 0; *chars = 0; return; }
    int c;
    *lines = 0;
    *chars = 0;
    while ((c = fgetc(f)) != EOF) {
        (*chars)++;
        if (c == '\n') (*lines)++;
    }
    fclose(f);
}

static const char *get_ext(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot) return "";
    if (dot == filename) return "";
    return dot;
}

static void walk(const char *full_path, const char *rel_path, struct FileList *fl) {
    DIR *d = opendir(full_path);
    if (!d) return;

    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

        char *full = (char *)malloc(strlen(full_path) + 1 + strlen(ent->d_name) + 1);
        if (!full) { closedir(d); return; }
        snprintf(full, strlen(full_path) + 1 + strlen(ent->d_name) + 1, "%s/%s", full_path, ent->d_name);

        char *rel;
        if (rel_path && strlen(rel_path) > 0) {
            rel = (char *)malloc(strlen(rel_path) + 1 + strlen(ent->d_name) + 1);
            if (!rel) { free(full); closedir(d); return; }
            snprintf(rel, strlen(rel_path) + 1 + strlen(ent->d_name) + 1, "%s/%s", rel_path, ent->d_name);
        } else {
            rel = strdup(ent->d_name);
            if (!rel) { free(full); closedir(d); return; }
        }

        struct stat st;
        if (lstat(full, &st) != 0) {
            free(full);
            free(rel);
            continue;
        }

        if (S_ISLNK(st.st_mode)) {
            free(full);
            free(rel);
            continue;
        } else if (S_ISREG(st.st_mode)) {
            long lines, chars;
            count_file(full, &lines, &chars);
            const char *ext = get_ext(ent->d_name);
            file_list_add(fl, rel, ext, lines, chars);
        } else if (S_ISDIR(st.st_mode)) {
            walk(full, rel, fl);
        }

        free(full);
        free(rel);
    }
    closedir(d);
}

static int cmp_by_ext_path(const void *a, const void *b) {
    const struct FileInfo *fa = (const struct FileInfo *)a;
    const struct FileInfo *fb = (const struct FileInfo *)b;
    int c = strcmp(fa->ext, fb->ext);
    if (c != 0) return c;
    return strcmp(fa->relpath, fb->relpath);
}

