#define N 3

void multiply(int a[N][N], int b[N][N], int c[N][N]) {
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            c[i][j] = 0;
            for (int k = 0; k < N; k++)
                c[i][j] += a[i][k] * b[k][j];
        }
}

long long determinant(int m[N][N], int size) {
    if (size == 1) return m[0][0];
    if (size == 2) return (long long)m[0][0] * m[1][1] - (long long)m[0][1] * m[1][0];

    long long det = 0;
    for (int col = 0; col < size; col++) {
        int sub[N-1][N-1];
        for (int i = 1; i < size; i++) {
            int si = 0;
            for (int j = 0; j < size; j++) {
                if (j == col) continue;
                sub[i-1][si] = m[i][j];
                si++;
            }
        }
        long long sign = (col % 2 == 0) ? 1 : -1;
        det += sign * (long long)m[0][col] * determinant(sub, size - 1);
    }
    return det;
}

