#include <ctype.h>

typedef enum {
    JT_NULL,
    JT_BOOL,
    JT_NUMBER,
    JT_STRING,
    JT_ARRAY,
    JT_OBJECT
} json_type;

typedef struct json_value json_value;

struct json_value {
    json_type type;
    union {
        int boolean;
        double number;
        char *string;
        struct {
            json_value **items;
            size_t count;
            size_t cap;
        } array;
        struct {
            char **keys;
            json_value **values;
            size_t count;
            size_t cap;
        } object;
    } u;
};

/* ---------- Parser ---------- */

typedef struct {
    const char *s;
    size_t pos;
} parser;

static void skip_ws(parser *p) {
    while (p->s[p->pos] && (p->s[p->pos] == ' ' || p->s[p->pos] == '\t' ||
           p->s[p->pos] == '\n' || p->s[p->pos] == '\r'))
        p->pos++;
}

static char *parse_string_raw(parser *p) {
    if (p->s[p->pos] != '"') return NULL;
    p->pos++;
    size_t cap = 64, len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) return NULL;
    while (p->s[p->pos] && p->s[p->pos] != '"') {
        char c = p->s[p->pos];
        if (c == '\\') {
            p->pos++;
            char e = p->s[p->pos];
            char out;
            switch (e) {
                case '"': out = '"'; break;
                case '\\': out = '\\'; break;
                case '/': out = '/'; break;
                case 'b': out = '\b'; break;
                case 'f': out = '\f'; break;
                case 'n': out = '\n'; break;
                case 'r': out = '\r'; break;
                case 't': out = '\t'; break;
                case 'u': {
                    unsigned int code = 0;
                    for (int i = 0; i < 4; i++) {
                        p->pos++;
                        char h = p->s[p->pos];
                        code <<= 4;
                        if (h >= '0' && h <= '9') code |= (h - '0');
                        else if (h >= 'a' && h <= 'f') code |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') code |= (h - 'A' + 10);
                    }
                    /* Encode as UTF-8 */
                    if (code < 0x80) {
                        if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)code;
                    } else if (code < 0x800) {
                        if (len + 2 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)(0xC0 | (code >> 6));
                        buf[len++] = (char)(0x80 | (code & 0x3F));
                    } else {
                        if (len + 3 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)(0xE0 | (code >> 12));
                        buf[len++] = (char)(0x80 | ((code >> 6) & 0x3F));
                        buf[len++] = (char)(0x80 | (code & 0x3F));
                    }
                    p->pos++;
                    continue;
                }
                default: out = e; break;
            }
            p->pos++;
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = out;
        } else {
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
