/* ---------- Canonical string for comparison ---------- */

typedef struct {
    char *buf;
    size_t len;
    size_t cap;
} strbuf;

static void sb_init(strbuf *sb) {
    sb->cap = 256;
    sb->len = 0;
    sb->buf = (char *)malloc(sb->cap);
    sb->buf[0] = '\0';
}

static void sb_append(strbuf *sb, const char *s, size_t n) {
    if (sb->len + n + 1 > sb->cap) {
        while (sb->len + n + 1 > sb->cap) sb->cap *= 2;
        sb->buf = realloc(sb->buf, sb->cap);
    }
    memcpy(sb->buf + sb->len, s, n);
    sb->len += n;
    sb->buf[sb->len] = '\0';
}

static void sb_append_cstr(strbuf *sb, const char *s) {
    sb_append(sb, s, strlen(s));
}

static void sb_append_char(strbuf *sb, char c) {
    sb_append(sb, &c, 1);
}

static void canonical_json(strbuf *sb, const json_value *v) {
    switch (v->type) {
        case JT_NULL:
            sb_append_cstr(sb, "null");
            break;
        case JT_BOOL:
            sb_append_cstr(sb, v->u.boolean ? "true" : "false");
            break;
        case JT_NUMBER: {
