static int json_equal(const json_value *a, const json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JT_NULL: return 1;
        case JT_BOOL: return a->u.boolean == b->u.boolean;
        case JT_NUMBER: return a->u.number == b->u.number;
        case JT_STRING: return strcmp(a->u.string, b->u.string) == 0;
        case JT_ARRAY:
            if (a->u.array.count != b->u.array.count) return 0;
            for (size_t i = 0; i < a->u.array.count; i++)
                if (!json_equal(a->u.array.items[i], b->u.array.items[i])) return 0;
            return 1;
        case JT_OBJECT:
            if (a->u.object.count != b->u.object.count) return 0;
            for (size_t i = 0; i < a->u.object.count; i++) {
                int found = 0;
                for (size_t j = 0; j < b->u.object.count; j++) {
                    if (strcmp(a->u.object.keys[i], b->u.object.keys[j]) == 0) {
                        if (!json_equal(a->u.object.values[i], b->u.object.values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
