            if (found_in_b) {
                result->u.object.values[result->u.object.count] = deep_merge(a->u.object.values[i], b->u.object.values[bidx]);
            } else {
                result->u.object.values[result->u.object.count] = deep_copy(a->u.object.values[i]);
            }
            result->u.object.count++;
        }

        for (size_t j = 0; j < b->u.object.count; j++) {
            const char *key = b->u.object.keys[j];
            int found_in_a = 0;
            for (size_t i = 0; i < a->u.object.count; i++) {
                if (strcmp(key, a->u.object.keys[i]) == 0) {
                    found_in_a = 1;
                    break;
                }
            }
            if (!found_in_a) {
                if (result->u.object.count >= result->u.object.cap) {
                    result->u.object.cap = result->u.object.cap ? result->u.object.cap * 2 : 8;
                    result->u.object.keys = realloc(result->u.object.keys, result->u.object.cap * sizeof(char *));
                    result->u.object.values = realloc(result->u.object.values, result->u.object.cap * sizeof(json_value *));
                }
                result->u.object.keys[result->u.object.count] = strdup(key);
                result->u.object.values[result->u.object.count] = deep_copy(b->u.object.values[j]);
                result->u.object.count++;
            }
        }
        return result;
    }

    if (a->type == JT_ARRAY && b->type == JT_ARRAY) {
        json_value *result = (json_value *)calloc(1, sizeof(json_value));
        result->type = JT_ARRAY;
        result->u.array.count = 0;
        result->u.array.cap = 0;
        result->u.array.items = NULL;

        for (size_t i = 0; i < a->u.array.count; i++) {
            if (result->u.array.count >= result->u.array.cap) {
                result->u.array.cap = result->u.array.cap ? result->u.array.cap * 2 : 8;
                result->u.array.items = realloc(result->u.array.items, result->u.array.cap * sizeof(json_value *));
            }
            result->u.array.items[result->u.array.count] = deep_copy(a->u.array.items[i]);
            result->u.array.count++;
        }

        for (size_t j = 0; j < b->u.array.count; j++) {
            int dup = 0;
            for (size_t i = 0; i < result->u.array.count; i++) {
                if (json_equal(result->u.array.items[i], b->u.array.items[j])) {
                    dup = 1;
                    break;
                }
            }
            if (!dup) {
                if (result->u.array.count >= result->u.array.cap) {
                    result->u.array.cap = result->u.array.cap ? result->u.array.cap * 2 : 8;
                    result->u.array.items = realloc(result->u.array.items, result->u.array.cap * sizeof(json_value *));
                }
                result->u.array.items[result->u.array.count] = deep_copy(b->u.array.items[j]);
                result->u.array.count++;
            }
        }
        return result;
    }

    /* Scalar conflict or type mismatch: B overrides A */
    return deep_copy(b);
}

/* ---------- Pretty Print (sorted keys) ---------- */

static void print_json(FILE *out, const json_value *v, int indent) {
    switch (v->type) {
        case JT_NULL:
            fprintf(out, "null");
            break;
        case JT_BOOL:
            fprintf(out, "%s", v->u.boolean ? "true" : "false");
            break;
        case JT_NUMBER: {
            double d = v->u.number;
            if (d == (long long)d && fabs(d) < 9.0e15) {
                fprintf(out, "%lld", (long long)d);
            } else {
                fprintf(out, "%.17g", d);
            }
            break;
        }
        case JT_STRING: {
            fputc('"', out);
            for (const char *c = v->u.string; *c; c++) {
                switch (*c) {
                    case '"': fputs("\\\"", out); break;
                    case '\\': fputs("\\\\", out); break;
                    case '\b': fputs("\\b", out); break;
                    case '\f': fputs("\\f", out); break;
                    case '\n': fputs("\\n", out); break;
                    case '\r': fputs("\\r", out); break;
                    case '\t': fputs("\\t", out); break;
                    default:
                        if ((unsigned char)*c < 0x20) {
                            fprintf(out, "\\u%04x", (unsigned char)*c);
                        } else {
                            fputc(*c, out);
                        }
                }
            }
            fputc('"', out);
            break;
        }
        case JT_ARRAY: {
            if (v->u.array.count == 0) {
                fprintf(out, "[]");
                return;
            }
            fprintf(out, "[\n");
            for (size_t i = 0; i < v->u.array.count; i++) {
                for (int k = 0; k < indent + 1; k++) fprintf(out, "  ");
                print_json(out, v->u.array.items[i], indent + 1);
                if (i < v->u.array.count - 1) fputc(',', out);
                fputc('\n', out);
            }
            for (int k = 0; k < indent; k++) fprintf(out, "  ");
            fputc(']', out);
            break;
        }
        case JT_OBJECT: {
            if (v->u.object.count == 0) {
                fprintf(out, "{}");
                return;
            }
            size_t n = v->u.object.count;
            const char **keys = (const char **)malloc(n * sizeof(char *));
            const json_value **vals = (const json_value **)malloc(n * sizeof(json_value *));
            for (size_t i = 0; i < n; i++) {
                keys[i] = v->u.object.keys[i];
                vals[i] = v->u.object.values[i];
            }
            for (size_t i = 1; i < n; i++) {
                const char *kk = keys[i];
                const json_value *vv = vals[i];
                size_t j = i;
                while (j > 0 && strcmp(keys[j-1], kk) > 0) {
                    keys[j] = keys[j-1];
                    vals[j] = vals[j-1];
                    j--;
                }
                keys[j] = kk;
                vals[j] = vv;
            }
            fprintf(out, "{\n");
            for (size_t i = 0; i < n; i++) {
                for (int k = 0; k < indent + 1; k++) fprintf(out, "  ");
                fputc('"', out);
                for (const char *c = keys[i]; *c; c++) {
                    switch (*c) {
                        case '"': fputs("\\\"", out); break;
                        case '\\': fputs("\\\\", out); break;
                        case '\n': fputs("\\n", out); break;
                        case '\r': fputs("\\r", out); break;
                        case '\t': fputs("\\t", out); break;
                        default: fputc(*c, out);
                    }
                }
                fprintf(out, "\": ");
                print_json(out, vals[i], indent + 1);
                if (i < n - 1) fputc(',', out);
                fputc('\n', out);
            }
            for (int k = 0; k < indent; k++) fprintf(out, "  ");
            fputc('}', out);
            free(keys);
            free(vals);
            break;
        }
    }
}

/* ---------- File reading ---------- */

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", path);
        return NULL;
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    fclose(f);
    return buf;
}

/* ---------- Main ---------- */

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    char *sa = read_file(path_a);
    if (!sa) return 1;
    char *sb = read_file(path_b);
    if (!sb) return 1;

    parser pa = { sa, 0 };
    parser pb = { sb, 0 };

    json_value *va = parse_value(&pa);
    json_value *vb = parse_value(&pb);

    if (!va || !vb) return 1;

    json_value *merged = deep_merge(va, vb);

    print_json(stdout, merged, 0);
    fputc('\n', stdout);

    free(sa);
    free(sb);
    return 0;
}
